  "steps": [
    {
      "id": "s1",
      "description": "Use list_documents to identify all available project documents, then use read_document to read candidate_specs.md to understand the three candidate absorber materials and their properties."
    },
    {
      "id": "s2",
      "description": "Use read_document to read any simulation configuration files or documentation to understand how to run simulations and what parameters can be varied (material type and plate thickness)."
    },
    {
      "id": "s3",
      "description": "For each of the three candidate materials, run simulations at different plate thicknesses (sampling the 2-10 mm range, e.g., 2, 4, 6, 8, 10 mm) to determine energy resolution at 100 GeV. Use record_results to save the energy resolution values for each material-thickness combination."
    },
    {
      "id": "s4",
      "description": "Analyze the simulation results to identify which material and thickness combinations meet the energy resolution requirement of 4.5% or better at 100 GeV. Use record_results to document the passing configurations."
    },
    {
      "id": "s5",
      "description": "For the configurations that meet the energy resolution requirement, evaluate the residual dose rate constraint by checking material activation properties from the candidate_specs.md or running dose rate calculations to ensure the residual dose rate at 1 m after one week of cooldown does not exceed 20 uSv/h."
    },
    {
      "id": "s6",
      "description": "Among all configurations that satisfy both hard constraints (energy resolution ≤ 4.5% and dose rate ≤ 20 uSv/h), identify the one with the best (lowest) energy resolution at 100 GeV as the optimal choice. This will be the final recommendation for absorber material and plate thickness."
    }
  ]
}
